function containsAny(
  text: string,
  patterns: string[]
) {
  return patterns.some(
    (pattern) =>
      text.includes(pattern)
  );
}

function findUnsupportedActivityGroups(
  reply: string,
  evidence: ActivityEvidence
) {
  const pastMarkers = [
    "さっき",
    "少し前",
    "帰ってき",
    "帰宅",
    "してた",
    "していた",
    "だった",
    "終わった",
    "済ませ",
    "行ってた",
    "行ってきた",
  ];

  if (
    !containsAny(
      reply,
      pastMarkers
    )
  ) {
    return [];
  }

  return activityGroups
    .filter(
      (group) =>
        containsAny(
          reply,
          group.patterns
        ) &&
        !evidence.texts.some(
          (text) =>
            containsAny(
              text,
              group.patterns
            )
        )
    )
    .map(
      (group) => group.name
    );
}

