function isWeatherText(
  text: string
) {
  return containsAny(
    text,
    [
      "天気",
      "雨",
      "霧雨",
      "雷",
      "降",
      "晴",
      "曇",
      "気温",
      "暑",
      "寒",
      "蒸し",
      "湿気",
      "湿度",
      "風",
    ]
  );
}

function hasRecentMisakiWeatherContext(
  history: ChatMessage[]
) {
  return history
    .slice(-8)
    .some(
      (item) =>
        item.role === "misaki" &&
        isWeatherText(
          item.text
        )
    );
}

function userAskedMisakiWeather(
  message: string
) {
  return (
    isWeatherText(message) &&
    containsAny(
      message,
      [
        "そっち",
        "そちら",
        "美咲",
      ]
    )
  );
}

function userIsActuallyInDanger(
  message: string
) {
  return containsAny(
