source.text:
"use client";

import { maintenanceMessage } from "../../lib/maintenance-result";

import { TEMPORARY_STATE_KEY, DEVICE_USER_KEY } from "../../lib/device-conversation";
import {
  useEffect,
  useState,
} from "react";

import {
  supabase,
} from "../../lib/supabase";

import {
  registerPushSubscription,
  sendTestPushNotification,
} from "../../lib/push-notifications";

type ChatMessage = {
  role: "misaki" | "user";
  text: string;
  requestId?: string;
};

type DailyUsage = {
  date: string;
  count: number;
};

type MisakiTodayMemory = {
  date: string;
  items: string[];
};

type Plan =
  | "free"
  | "premium";

type UsageRpcResult = {
  message_count?: number;
  remaining?: number;
  is_premium?: boolean;
};

type ApiUsage = {
  messageCount?: number;
  remaining?: number;
  isPremium?: boolean;
};

const STORAGE_KEY =
  "misaki-chat-history";

const MEMORY_KEY =
  "misaki-long-term-memory";

const RELATIONSHIP_KEY =
  "misaki-relationship-points";

const MISAKI_TODAY_MEMORY_KEY =
  "misaki-today-memory";

const MAX_MESSAGES = 60;

// 無料版は1日20往復まで
const FREE_DAILY_LIMIT = 20;

const INITIAL_MESSAGES:
  ChatMessage[] = [];



function getJapanDateKey() {
  return new Date()
    .toLocaleDateString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",
      }
    );
}

function getJapanCurrentTime() {
  return new Date()
    .toLocaleString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",

        weekday:
          "short",

        hour:
          "2-digit",

        minute:
          "2-digit",

        hour12:
          false,
      }
    );
}

function createEmptyTodayMemory():
  MisakiTodayMemory {
  return {
    date:
      getJapanDateKey(),

    items: [],
  };
}

function isPremiumActive(
  plan:
    | string
    | null
    | undefined,

  premiumUntil:
    | string
    | null
    | undefined
) {
  if (
    plan !==
    "premium"
  ) {
    return false;
  }

  if (
    !premiumUntil
  ) {
    return true;
  }

  const expiresAt =
    new Date(
      premiumUntil
    ).getTime();

  if (
    !Number.isFinite(
      expiresAt
    )
  ) {
    return false;
  }

  return (
    expiresAt >
    Date.now()
  );
}

function getFirstRpcRow<T>(
  value: unknown
): T | null {
  if (
    Array.isArray(
      value
    ) &&
    value.length >
      0
  ) {
    return value[0] as T;
  }

  if (
    value &&
    typeof value ===
      "object"
  ) {
    return value as T;
  }

  return null;
}

export default function ChatPage() {
  const [
    message,
    setMessage,
  ] =
    useState("");

  const [
    messages,
    setMessages,
  ] =
    useState<
      ChatMessage[]
    >(
      INITIAL_MESSAGES
    );

  const [replyFeedback, setReplyFeedback] = useState<Record<string, { rating: "good" | "bad"; reason?: string }>>({});

  const [
    memory,
    setMemory,
  ] =
    useState<
      string[]
    >([]);

  const [
    misakiTodayMemory,
    setMisakiTodayMemory,
  ] =
    useState<
      MisakiTodayMemory
    >(
      createEmptyTodayMemory()
    );

  const [
    relationshipPoints,
    setRelationshipPoints,
  ] =
    useState(0);

  const [
    dailyUsage,
    setDailyUsage,
  ] =
    useState<
      DailyUsage
    >({
      date:
        getJapanDateKey(),

      count:
        0,
    });

  const [
    plan,
    setPlan,
  ] =
    useState<
      Plan
    >(
      "free"
    );

  const [
    accountLoaded,
    setAccountLoaded,
  ] =
    useState(
      false
    );

  const [
    showPremium,
    setShowPremium,
  ] =
    useState(
      false
    );

  const [
    showMemory,
    setShowMemory,
  ] =
    useState(
      false
    );

  const [
    showMenu,
    setShowMenu,
  ] =
    useState(
      false
    );

  const [
    loading,
    setLoading,
  ] =
    useState(
      false
    );

  const [
    waitingOnReply,
    setWaitingOnReply,
  ] =
    useState(
      false
    );

  const [
    sendError,
    setSendError,
  ] =
    useState(
      ""
    );

  const [
    loaded,
    setLoaded,
  ] =
    useState(
      false
    );

  const [
    notificationPermission,
    setNotificationPermission,
  ] =
    useState<
      | "default"
      | "granted"
      | "denied"
      | "unsupported"
    >(
      "default"
    );

  const isPremium =
    plan ===
    "premium";

  const today =
    getJapanDateKey();

  const usageCountToday =
    dailyUsage.date ===
    today
      ? dailyUsage.count
      : 0;

  const freeRemaining =
    Math.max(
      0,
      FREE_DAILY_LIMIT -
        usageCountToday
    );

  const freeLimitReached =
    accountLoaded &&
    !isPremium &&
    usageCountToday >=
      FREE_DAILY_LIMIT;

  useEffect(
    () => {
      let active =
        true;

      async function loadEntitlement(
        userId:
          string
      ) {
        for (
          let attempt =
            0;
          attempt <
            5;
          attempt +=
            1
        ) {
          const {
            data,
            error,
          } =
            await supabase
              .from(
                "user_entitlements"
              )
              .select(
                "plan,premium_until"
              )
              .eq(
                "user_id",
                userId
              )
              .maybeSingle();

          if (
            error
          ) {
            throw error;
          }

          if (
            data
          ) {
            return isPremiumActive(
              data.plan,
              data.premium_until
            );
          }

          await new Promise(
            (
              resolve
            ) =>
              window.setTimeout(
                resolve,
                350
              )
          );
        }

        return false;
      }

      async function loadDailyUsage() {
        const {
          data,
          error,
        } =
          await supabase.rpc(
            "get_daily_message_usage"
          );

        if (
          error
        ) {
          throw error;
        }

        const usage =
          getFirstRpcRow<
            UsageRpcResult
          >(
            data
          );

        return {
          count:
            typeof usage
              ?.message_count ===
              "number"
              ? Math.max(
                  0,
                  Math.floor(
                    usage
                      .message_count
                  )
                )
              : 0,

          isPremium:
            usage
              ?.is_premium ===
            true,
        };
      }

      async function initializeAccount() {
        try {
          const {
            data:
              sessionData,
            error:
              sessionError,
          } =
            await supabase
              .auth
              .getSession();

          if (
            sessionError
          ) {
            throw sessionError;
          }

          let user =
            sessionData
              .session
              ?.user ??
            null;

          if (
            !user
          ) {
            const {
              data:
                signInData,
              error:
                signInError,
            } =
              await supabase
                .auth
                .signInAnonymously();

            if (
              signInError
            ) {
              throw signInError;
            }

            user =
              signInData
                .user ??
              null;
          }

          if (
            !user
          ) {
            throw new Error(
              "Supabase user was not created."
            );
          }

          const [
            entitlementPremium,
            usage,
          ] =
            await Promise
              .all([
                loadEntitlement(
                  user.id
                ),

                loadDailyUsage(),
              ]);

          if (
            !active
          ) {
            return;
          }

          const premium =
            entitlementPremium ||
            usage
              .isPremium;

          setPlan(
            premium
              ? "premium"
              : "free"
          );

          setDailyUsage({
            date:
              getJapanDateKey(),

            count:
              usage.count,
          });
        } catch (
          error
        ) {
          console.error(
            "Supabase account initialization failed:",
            error
          );

          if (
            active
          ) {
            setPlan(
              "free"
            );

            setDailyUsage({
              date:
                getJapanDateKey(),

              count:
                0,
            });
          }
        } finally {
          if (
            active
          ) {
            setAccountLoaded(
              true
            );
          }
        }
      }

      initializeAccount();

      return () => {
        active =
          false;
      };
    },
    []
  );

  useEffect(
    () => {
      if (
        !accountLoaded
      ) {
        return;
      }

      if (
        isPremium
      ) {
        setShowPremium(
          false
        );

        return;
      }

      if (
        usageCountToday >=
        FREE_DAILY_LIMIT
      ) {
        setShowPremium(
          true
        );
      }
    },
    [
      accountLoaded,
      isPremium,
      usageCountToday,
    ]
  );

  useEffect(
    () => {
      if (
        "serviceWorker" in
        navigator
      ) {
        navigator
          .serviceWorker
          .register(
            "/sw.js"
          )
          .then(
            (
              registration
            ) => {
              console.log(
                "Service Worker registered:",
                registration
              );
            }
          )
          .catch(
            (
              error
            ) => {
              console.error(
                "Service Worker registration failed:",
                error
              );
            }
          );
      }
    },
    []
  );

  useEffect(
    () => {
      if (
        !(
          "Notification" in
          window
        )
      ) {
        setNotificationPermission(
          "unsupported"
        );

        return;
      }

      setNotificationPermission(
        Notification
          .permission
      );
    },
    []
  );

  useEffect(() => {
    let active = true;
    function applyRoot(state: any) {
      if (!active || !state) return;
      if (Array.isArray(state.memory)) setMemory(state.memory);
      if (typeof state.relationshipPoints === "number") setRelationshipPoints(state.relationshipPoints);
      if (state.misakiTodayMemory) applyTodayMemory(state.misakiTodayMemory);
    }
    const receive = (event: Event) => applyRoot((event as CustomEvent).detail);
    const receiveHistory = (event: Event) => {
      const history = (event as CustomEvent).detail;
      if (active && Array.isArray(history)) setMessages(history.slice(-MAX_MESSAGES));
    };
    window.addEventListener("misaki-root-state", receive);
    window.addEventListener("misaki-history-state", receiveHistory);
    async function load() {
      try {
        // A full remount ends the previous page's in-flight UI send marker.
        sessionStorage.removeItem("misaki-chat-sending");
        const raw = localStorage.getItem(STORAGE_KEY);
        const cached = raw ? JSON.parse(raw) : [];
        if (Array.isArray(cached)) setMessages(cached.slice(-MAX_MESSAGES));
        const accessToken = await getAccessToken();
        const expectedOwner = localStorage.getItem(DEVICE_USER_KEY);
        const response = await fetch("/api/persona/history", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${accessToken}` },
          body: JSON.stringify({ action: "load", temporaryState: sessionStorage.getItem(TEMPORARY_STATE_KEY),
            pending: JSON.parse(sessionStorage.getItem("misaki-pending-chat-turn") || "null") }),
        });
        if (!response.ok) {
          const result = await response.json().catch(() => null);
          throw new Error(maintenanceMessage(response.status, result) || "美咲の状態を読み込めませんでした。");
        }
        const state = await response.json();
        const { data: latest } = await supabase.auth.getSession();
        if (!active || latest.session?.user.id !== expectedOwner || localStorage.getItem(DEVICE_USER_KEY) !== expectedOwner) return;
        applyRoot(state);
        const pending = JSON.parse(sessionStorage.getItem("misaki-pending-chat-turn") || "null");
        if (state.recoveredTurn || state.history?.some((item: any) => item.requestId === pending?.requestId)) {
          sessionStorage.removeItem("misaki-pending-chat-turn");
        }
        if (typeof state.temporaryState === "string") sessionStorage.setItem(TEMPORARY_STATE_KEY, state.temporaryState);
        // Permanent history is canonical. Anonymous history remains a display cache.
        if (active && Array.isArray(state.history) && (!state.ephemeral || state.recoveredTurn || cached.length === 0)) setMessages(state.history);
        for (const key of [MEMORY_KEY, RELATIONSHIP_KEY, MISAKI_TODAY_MEMORY_KEY]) localStorage.removeItem(key);
      } catch (error) {
        if (active) setSendError(error instanceof Error ? error.message : "状態を読み込めませんでした。");
      } finally { if (active) setLoaded(true); }
    }
    void load();
    return () => {
      active = false;
      window.removeEventListener("misaki-root-state", receive);
      window.removeEventListener("misaki-history-state", receiveHistory);
    };
  }, []);

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        const limitedMessages =
          messages
            .slice(
              -MAX_MESSAGES
            );

        localStorage
          .setItem(
            STORAGE_KEY,

            JSON.stringify(
              limitedMessages
            )
          );
      } catch (
        error
      ) {
        console.error(
          "Failed to save chat history:",
          error
        );
      }
    },
    [
      messages,
      loaded,
    ]
  );

  async function getAccessToken() {
    const {
      data,
      error,
    } =
      await supabase
        .auth
        .getSession();

    if (
      error
    ) {
      throw error;
    }

    const accessToken =
      data
        .session
        ?.access_token;

    if (
      !accessToken
    ) {
      throw new Error(
        "ログイン情報を確認できませんでした。ページを再読み込みしてね。"
      );
    }

    return accessToken;
  }

  function applyApiUsage(
    value:
      unknown
  ) {
    if (
      !value ||
      typeof value !==
        "object"
    ) {
      return;
    }

    const usage =
      value as
        ApiUsage;

    if (
      usage
        .isPremium ===
      true
    ) {
      setPlan(
        "premium"
      );
    }

    if (
      typeof usage
        .messageCount ===
        "number" &&
      Number.isFinite(
        usage
          .messageCount
      )
    ) {
      setDailyUsage({
        date:
          getJapanDateKey(),

        count:
          Math.max(
            0,

            Math.floor(
              usage
                .messageCount
            )
          ),
      });
    }
  }

  async function requestNotificationPermission() {
    if (
      !(
        "Notification" in
        window
      )
    ) {
      alert(
        "この環境では通知機能を利用できません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    if (
      !(
        "serviceWorker" in
        navigator
      )
    ) {
      alert(
        "この環境では通知機能を利用できません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    if (
      !(
        "PushManager" in
        window
      )
    ) {
      alert(
        "このブラウザはPush通知に対応していません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    try {
      await navigator
        .serviceWorker
        .ready;

      const permission =
        await Notification
          .requestPermission();

      setNotificationPermission(
        permission
      );

      if (
        permission ===
        "denied"
      ) {
        alert(
          "通知が許可されませんでした。端末の設定から美咲の通知を許可してください。"
        );

        return;
      }

      if (
        permission !==
        "granted"
      ) {
        return;
      }

      await registerPushSubscription();

      const accessToken =
        await getAccessToken();

      try {
        await sendTestPushNotification(
          accessToken
        );

        alert(
          "通知をONにしました。今、美咲からテスト通知を送ったよ。"
        );
      } catch (
        testError
      ) {
        console.error(
          "Test push notification failed:",
          testError
        );

        alert(
          "通知端末の登録はできました。テスト通知だけ送信できませんでした。"
        );
      }
    } catch (
      error
    ) {
      console.error(
        "Push notification setup error:",
        error
      );

      const errorMessage =
        error instanceof
        Error
          ? error.message
          : "通知の設定に失敗しました。";

      alert(
        errorMessage
      );
    }
  }

  async function changeStoredState(action: string, value?: string) {
    if (loading || sessionStorage.getItem("misaki-pending-chat-turn")) throw new Error("返信を確認してから変更してください。未受信の場合は再読み込みで確認できます。");
    const accessToken = await getAccessToken();
    const { data: owner } = await supabase.auth.getSession();
    const expectedOwner = owner.session?.user.id;
    const response = await fetch("/api/persona/history", {
      method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${accessToken}` },
      body: JSON.stringify({ action, value, temporaryState: sessionStorage.getItem(TEMPORARY_STATE_KEY) }),
    });
    if (!response.ok) {
      const result = await response.json().catch(() => null);
      throw new Error(maintenanceMessage(response.status, result) || "保存できませんでした。もう一度お試しください。");
    }
    const state = await response.json();
    const { data: latest } = await supabase.auth.getSession();
    if (!expectedOwner || latest.session?.user.id !== expectedOwner || localStorage.getItem(DEVICE_USER_KEY) !== expectedOwner) throw new Error("アカウントが変更されました。");
    if (Array.isArray(state.memory)) setMemory(state.memory);
    if (typeof state.temporaryState === "string") sessionStorage.setItem(TEMPORARY_STATE_KEY, state.temporaryState);
  }
  async function resetChat() {
    if (!window.confirm("美咲との会話履歴をリセットしますか？")) return;
    try {
      await changeStoredState("clearHistory");
      localStorage.removeItem(STORAGE_KEY); setMessages([]); setMessage(""); setShowMenu(false);
    } catch (error) { setSendError((error as Error).message); }
  }
  async function deleteMemory(index: number) {
    if (!window.confirm("この記憶を削除しますか？")) return;
    try { await changeStoredState("deleteMemory", memory[index]); }
    catch (error) { setSendError((error as Error).message); }
  }
  async function resetMemory() {
    if (!memory.length || !window.confirm("美咲の長期記憶をすべて削除しますか？\n会話履歴は残ります。")) return;
    try { await changeStoredState("clearMemory"); }
    catch (error) { setSendError((error as Error).message); }
  }

  function openPremium() {
    if (
      isPremium
    ) {
      return;
    }

    setShowPremium(
      true
    );
  }

  function startPremium() {
    alert(
      "プレミアム決済は次の工程で接続します。今はまだ料金は発生しません。"
    );
  }

  function applyTodayMemory(
    value:
      unknown
  ) {
    if (
      !value ||
      typeof value !==
        "object"
    ) {
      return;
    }

    const data =
      value as {
        date?:
          unknown;

        items?:
          unknown;
      };

    const currentDate =
      getJapanDateKey();

    if (
      data.date !==
        currentDate ||
      !Array.isArray(
        data.items
      )
    ) {
      return;
    }

    const items =
      data
        .items
        .filter(
          (
            item:
              unknown
          ) =>
            typeof item ===
              "string" &&
            item
              .trim()
              .length >
              0
        )
        .map(
          (
            item
          ) =>
            (
              item as string
            )
              .trim()
        )
        .slice(
          -12
        );

    setMisakiTodayMemory({
      date:
        currentDate,

      items:
        Array.from(
          new Set(
            items
          )
        ),
    });
  }

  async function sendMessage() {
    const text =
      message
        .trim();

    if (
      !text ||
      loading ||
      !accountLoaded || !loaded
    ) {
      return;
    }

    const currentDate =
      getJapanDateKey();

    if (
      !isPremium &&
      usageCountToday >=
        FREE_DAILY_LIMIT
    ) {
      setShowPremium(
        true
      );

      return;
    }

    setLoading(
      true
    );

    setSendError(
      ""
    );

    setWaitingOnReply(false);
    const waitingTimer = window.setTimeout(() => setWaitingOnReply(true), 1_800);

    let receivedResponse = false;
    let activeRequestId: string | null = null;
    try {
      const accessToken = await getAccessToken();
      const { data: sessionData } = await supabase.auth.getSession();
      const expectedOwner = sessionData.session?.user.id;
      const expectedAnonymous = sessionData.session?.user.is_anonymous === true;
      const pending = JSON.parse(sessionStorage.getItem("misaki-pending-chat-turn") || "null");
      if (pending?.owner === expectedOwner && pending.message !== text) throw new Error("前の返信を確認できていません。同じメッセージを再送するか、再読み込みで確認してください。");
      const reuse = pending?.message === text && pending?.owner === expectedOwner;
      const requestId = reuse ? pending.requestId : crypto.randomUUID();
      activeRequestId = requestId;
      const temporaryState = reuse ? pending.temporaryState : sessionStorage.getItem(TEMPORARY_STATE_KEY);
      sessionStorage.setItem("misaki-pending-chat-turn", JSON.stringify({ requestId, message: text, owner: expectedOwner, temporaryState }));
      sessionStorage.setItem("misaki-chat-sending", requestId);

      const userMessage:
        ChatMessage = {
          role:
            "user",

          text, requestId,
        };

      const newMessages =
        [
          ...messages,
          ...(reuse && messages.some(item => item.requestId === requestId) ? [] : [userMessage]),
        ]
          .slice(
            -MAX_MESSAGES
          );

      setMessages(
        newMessages
      );

      setMessage(
        ""
      );


      const currentTime =
        getJapanCurrentTime();

      const todayMemoryForRequest =
        misakiTodayMemory
          .date ===
          currentDate
          ? misakiTodayMemory
          : {
              date:
                currentDate,

              items:
                [],
            };

      const res =
        await fetch(
          "/api/chat",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/json",

              Authorization:
                `Bearer ${accessToken}`,
            },

            body:
              JSON.stringify({
                message:
                  text,

                history:
                  messages
                    .slice(
                      -MAX_MESSAGES
                    ),

                memory,

                misakiTodayMemory:
                  todayMemoryForRequest,

                currentTime,

                requestId,
                temporaryState,
              }),
          }
        );

      const data = await res.json();
      receivedResponse = true;
      const { data: latest } = await supabase.auth.getSession();
      if (latest.session?.user.id !== expectedOwner && !(expectedAnonymous && latest.session?.user.is_anonymous)) return;
      const maintenance = maintenanceMessage(res.status, data);
      if (maintenance) {
        setSendError(maintenance);
        // A retry may have committed before its response was lost. Keep its
        // recovery marker and history until the server can confirm the result.
        receivedResponse = !reuse;
        if (!reuse) setMessages(prev => prev.filter(item => item.requestId !== requestId));
        setMessage(text);
        return;
      }
      sessionStorage.removeItem("misaki-pending-chat-turn");

      applyApiUsage(
        data?.usage
      );

      if (
        res.status ===
        429
      ) {
        setShowPremium(
          true
        );

        setMessages(
          (
            prev
          ) =>
            prev
              .filter(
                (
                  item,
                  index
                ) =>
                  !(
                    index ===
                      prev.length -
                        1 &&
                    item.role ===
                      "user" &&
                    item.text ===
                      text
                  )
              )
        );

        return;
      }

      if (
        !res.ok
      ) {
        throw new Error(
          data?.error ||
            "通信に失敗しました"
        );
      }

      if (
        Array.isArray(
          data.memory
        )
      ) {
        setMemory(
          data.memory
            .filter(
              (
                item:
                  unknown
              ) =>
                typeof item ===
                "string"
            )
        );
      }

      applyTodayMemory(
        data
          .misakiTodayMemory
      );

      if (typeof data.relationshipPoints === "number") setRelationshipPoints(data.relationshipPoints);
      if (typeof data.temporaryState === "string") sessionStorage.setItem(TEMPORARY_STATE_KEY, data.temporaryState);

      setMessages(
        (
          prev
        ) =>
          [
            ...prev,

            {
              role:
                "misaki" as const,

              text:
                data.reply ||
                "返事を取得できませんでした。",
              requestId,
            },
          ]
            .slice(
              -MAX_MESSAGES
            )
      );
    } catch (
      error:
        any
    ) {
      console.error(
        "Chat message error:",
        error
      );

      setSendError(
        error instanceof Error &&
        error.message
          ? error.message
          : "返事を受け取れませんでした。もう一度送ってみてね。"
      );
    } finally {
      if (receivedResponse && JSON.parse(sessionStorage.getItem("misaki-pending-chat-turn") || "null")?.requestId === activeRequestId) sessionStorage.removeItem("misaki-pending-chat-turn");
      if (sessionStorage.getItem("misaki-chat-sending") === activeRequestId) sessionStorage.removeItem("misaki-chat-sending");
      window.clearTimeout(waitingTimer);
      setWaitingOnReply(false);
      setLoading(
        false
      );
    }
  }

  async function rateReply(requestId: string, rating: "good" | "bad", reason?: string) {
    const { data } = await supabase.auth.getSession();
    const token = data.session?.access_token;
    if (!token) return;
    const previous = replyFeedback[requestId];
    setReplyFeedback(prev => ({ ...prev, [requestId]: { rating, ...(reason ? { reason } : {}) } }));
    try {
      const response = await fetch("/api/feedback/reply", {
        method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ requestId, rating, reason }),
      });
      if (!response.ok) throw new Error("feedback failed");
    } catch {
      setReplyFeedback(prev => { const next = { ...prev }; if (previous) next[requestId] = previous; else delete next[requestId]; return next; });
